// Measure Core Web Vitals with web-vitals library
import { getLCP, getCLS, getINP } from 'web-vitals';

getLCP(metric => console.log('LCP:', metric.value));
getCLS(metric => console.log('CLS:', metric.value));
getINP(metric => console.log('INP:', metric.value));

// Prevent CLS: always set width and height on images
<img src="project-photo.jpg" width="800" height="600" alt="Project" loading="lazy">

// Lazy load below-fold images
<img src="product-preview.jpg" loading="lazy" decoding="async">

/* Mobile-first base styles */
.project-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 15px;
  padding: 15px;
}

/* Progressive enhancement */
@media (min-width: 768px) {
  .project-grid { grid-template-columns: 1fr 1fr; }
}
@media (min-width: 1024px) {
  .project-grid { grid-template-columns: repeat(3, 1fr); }
}

/* Fluid typography */
h1 { font-size: clamp(1.5rem, 4vw, 3rem); }

/* CSS font with swap for performance */
@font-face {
  font-family: 'Inter';
  src: url('/fonts/inter.woff2') format('woff2');
  font-display: swap; /* Prevents invisible text flash */
}

<!-- Responsive image with WebP and fallback -->
<picture>
  <source srcset="hero.avif" type="image/avif">
  <source srcset="hero.webp" type="image/webp">
  <img src="hero.jpg" alt="Dashboard preview" width="1200" height="630">
</picture>
